2\26\132\119\87\167\116\14\167\27\244\81\79\175\114\9\178\86\245","\35\206\17\96\211\58\212\22"),v7("\0\192\134\46\200\177\187\137\57\219\154\45\200\174\173\219\42\142\143\56\155\172\232\222\54\207\157\49\141\170\233\137\26\142\155\60\137\188\232\221\59\207\157\120\200\145\232\196\50\202\140\121\156\176\169\221\115\219\153\120","\169\83\174\233\89\232\216\200"),"I'm not old! That's— nobody said old! Sorry! Nevermind!"},[v7("\104\61\116\19\135\233\200\37\111\59\126","\118\60\114\59\93\216\171\137")]={v7("\101\200\77\240\253\18\135\10\170\158\83\218\87\237\185\18\206\75\240\252\95\208\4\234\189\95\204\4\246\181\85\193\80\165\252\107\198\81\164\187\93\221\4\233\165\18\199\69\233\185\18\219\77\227\180\70\136","\220\50\169\36\132"),"We're for sure friends! Of course! Just us Mains! Hahaha!",v7("\211\134\31\162\248\130\76\184\226\199\13\241\247\142\31\185\176\199\42\184\226\143\76\176\227\130\76\190\253\131\9\163\177\147\4\176\255\199\24\163\244\130\31\240\177\174\76\178\249\130\15\186\244\131\77\241\197\144\5\178\244\198","\209\145\231\108"),v7("\112\97\0\12\206\192\98\87\36\30\8\202\133\32\92\36\6\77\204\202\98\77\41\13\77\215\198\39\88\47\73\77\241\133\42\88\55\13\77\218\192\39\87\97\28\2\152\196\98\93\40\15\77\203\204\54\92\96\72\62\209\200\43\85\32\26\77\220\208\49\77\96","\66\57\65\104\109\184\165"),v7("\155\2\233\86\165\181\10\236\91\165\191\14\255\80\165\188\25\245\75\235\185\75\252\81\247\184\29\255\76\164\253\56\242\81\242\240\4\252\88\246\252\75\205\81\235\185\14\232\88\240\177\74","\133\221\107\154\62"),v7("\242\24\245\195\70\209\34\210\27\245\246\70\204\37\200\94\161\238\7\202\52\218\12\245\224\69\205\36\207\94\161\233\66\130\21\222\8\186\239\78\195\63\151\94\156\161\79\195\39\222\94\180\161\83\195\61\208\95\245\209\85\199\33\218\12\176\229\6\130\23\212\12\184\224\83\214\52\223\95","\81\187\126\213\129\39\162"),"Bassie has scales, I have a shell! We're both wearing the correct outfit!","I almost said something and then didn't! That's normal! That's a normal thing I do!"},[v7("\182\129\31\221\138\177\142\2\218","\196\229\209\77\148")]={"Sprinting! Or— whatever that was! It was fast! I noticed the fast!","Ooo, speed! I'm not built for speed! I'm built for gently holding small bones!","Go! Go! I'll keep up! I won't keep up! But I'll keep going!","That's the fast one! I remember the fast one! I've read about velocity!","Careful on the corners! Actually— don't be careful! Be fast! Sorry!","You're so quick! I'm the slow one of the team and I've made peace with it!","Fast fast fast! That's the whole sentence! I panicked!",v7("\117\192\127\92\81\251\198\66\149\112\92\122\243\193\75\220\124\21\80\231\222\6\149\69\20\88\235\141\80\208\99\25\29\240\216\78\217\101\92\91\253\223\7\220\101\93\29\203\194\82\149\125\19\82\249\141\69\192\120\16\73\178\203\72\199\49\21\73\179","\173\39\181\17\124\61\146"),"If you get too far ahead I'll just— narrate! From back here! Cheerfully!","Speed without stamina! That's the dream! That's actually my dream!","I'm impressed and slightly dizzy! Mostly impressed!"},[v7("\73\236\193\11\166\78\227\220\4\174","\232\26\188\147\66")]={"Slower now? Good! I mean— not good! Just easier to keep up with!",v7("\55\224\229\16\51\1\238\166\21\124\7\236\231\23\51\2\224\234\16\122\27\230\167\91\93\26\243\235\26\127\85\232\245\91\126\12\161\224\26\101\26\244\244\18\103\16\161\245\11\118\16\229\167\91\93\26\161\233\29\117\16\239\229\30\51\1\238\166\29\114\6\245\167","\19\117\129\134\123"),v7("\12\8\200\15\117\99\16\15\198\1\61\45\36\67\205\25\35\45\98\67\228\15\116\47\38\4\218\86\39\34\58\67\221\30\53\45\40\67\208\25\33\98\99\42\137\5\53\58\99\23\193\23\58\40\99\26\198\3\117","\67\67\99\169\118\84"),v7("\59\37\240\15\64\162\246\166\18\47\225\14\19\145\235\179\3\62\164\15\125\185\237\246\5\56\224\78\71\247\185\152\7\63\241\93\82\186\184\246\53\43\246\15\71\190\248\162\66\43\165\77\82\178\185\165\22\37\245\16","\214\98\74\133\47\51\214\153"),"Walking! Remember walking? We're doing that again! Lovely!","I'll catch my breath with you! Team breathing! Is that a thing? It's a thing now!",v7("\57\66\127\99\118\69\74\67\117\117\125\68\74\67\127\102\118\23\30\71\125\113\51\67\5\14\124\123\124\92\74\79\100\52\103\95\3\64\119\103\50\23\44\65\99\103\122\91\25\14\113\102\118\23\7\65\99\96\127\78\74\66\127\123\120\94\4\73\49","\55\106\46\16\20\19"),"That's fine! Fast is a sometimes food! Walking is the meal!","No more sprint! I'll stop narrating the wind! It was getting weird!",v7("\96\251\190\57\61\59\23\9\175\186\53\118\56\18\90\175\242\32\55\44\7\8\251\155\112\55\50\0\70\251\190\57\61\59\83\93\179\187\35\118\46\18\91\175\243\112\31\126\31\64\176\183\112\59\49\0\93\251\162\49\36\42\0\5\251\186\63\56\59\0\93\183\171\113","\115\41\219\210\80\86\94")},[v7("\147\98\192\54\254","\91\192\41\137\122\178")]={"PERFECT! Did you see that? I saw that! I'm writing it down!",v7("\99\45\203\252\23\50\203\251\23\36\138\239\69\32\203\252\22\101\235\168\69\32\203\228\23\34\216\237\86\49\139\168\126\101\194\237\86\55\206\168\67\45\207\168\68\42\223\230\83\100\138\220\95\32\138\239\88\42\206\168\68\42\223\230\83\100","\136\55\69\170"),v7("\205\244\19\63\150\251\44\195\231\238\81\122\255\179\46\194\246\241\20\122\216\246\59\200\241\188\80\23\207\179\37\204\237\249\3\122\215\225\40\141\229\242\2\122\198\252\36\195\247\244\30\61\150\242\57\141\241\242\19\49\197\178","\173\131\157\112\90\182\147\77"),"That's the timing of a naturalist! Precise! Steady! I'm taking notes!","Right in the middle! That's where the good zone lives! You found it!",v7("\61\4\37\6\14\87\96\32\8\19\33\19\91\86\9\71\17\19\37\23\90\5\33\30\19\24\39\71\29\4\37\6\14\87\96\46\14\86\55\6\9\86\39\21\31\23\52\71\14\30\47\18\29\30\97","\103\122\118\64"),"You made that look intentional! Was it? Doesn't matter! Great!",v7("\195\227\25\200\252\252\176\201\19\208\229\188\252\168\3\207\249\177\252\169\80\234\255\169\176\228\5\199\251\252\176\197\31\215\228\177\233\168\30\203\228\253\252\253\19\207\177\253\215\250\21\197\228\252","\221\144\136\112\164\144"